{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(put_mode, chan_mode, trig, actions):
        committed = {}
        txn = {"main": None, "other": None}
        tc_main = 0
        tc_other = 0
        last_chan = 0
        for a in actions:
            op = a.get("op")
            conn = a.get("connection", "main")
            if op == "begin":
                txn[conn] = {}
            elif op == "commit":
                t = txn[conn]
                if t is not None:
                    for k in t:
                        committed[k] = t[k]
                txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op == "put":
                k = a.get("key")
                v = a.get("value")
                t = txn[conn]
                target = committed if t is None else t
                existed = k in target
                if existed:
                    if put_mode == "ignore":
                        changed = 0
                        inserted = 0
                    else:
                        target[k] = v
                        changed = 1
                        inserted = 0
                else:
                    target[k] = v
                    changed = 1
                    inserted = 1
                extra = 0
                if trig and inserted:
                    extra = 1
                if chan_mode == "changes":
                    last_chan = changed
                elif chan_mode == "tc_main":
                    tc_main += changed + extra
                    last_chan = tc_main
                else:
                    if conn == "main":
                        tc_main += changed + extra
                    else:
                        tc_other += changed + extra
                    last_chan = tc_main + tc_other
            elif op == "update":
                k = a.get("key")
                v = a.get("value")
                t = txn[conn]
                target = committed if t is None else t
                if k in target:
                    target[k] = v
                    changed = 1
                else:
                    changed = 0
                if chan_mode == "changes":
                    last_chan = changed
                elif chan_mode == "tc_main":
                    tc_main += changed
                    last_chan = tc_main
                else:
                    if conn == "main":
                        tc_main += changed
                    else:
                        tc_other += changed
                    last_chan = tc_main + tc_other
            elif op == "delete":
                k = a.get("key")
                t = txn[conn]
                target = committed if t is None else t
                if k in target:
                    del target[k]
                    changed = 1
                else:
                    changed = 0
                if chan_mode == "changes":
                    last_chan = changed
                elif chan_mode == "tc_main":
                    tc_main += changed
                    last_chan = tc_main
                else:
                    if conn == "main":
                        tc_main += changed
                    else:
                        tc_other += changed
                    last_chan = tc_main + tc_other
        return last_chan, len(committed), sum(committed.values())

    modes = ["ignore", "replace", "update"]
    chans = ["changes", "tc_main", "tc_both"]
    trigs = [False, True]
    candidates = []
    for pm in modes:
        for cm in chans:
            for tg in trigs:
                ok = True
                for r in hist:
                    acts = r.get("actions", [])
                    obs = r.get("observed", {})
                    ch, cc, cs = simulate(pm, cm, tg, acts)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tg))

    goal = context.get("goal")
    acts = context.get("actions", [])
    vals = set()
    for pm, cm, tg in candidates:
        ch, cc, cs = simulate(pm, cm, tg, acts)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Predicts channel, committed_count, or committed_sum for the disclosed 18-member SQLite family by simulating all put/channel/trigger combinations and keeping those consistent with calibration receipts.", "lesson": "Simulate put modes (OR IGNORE, OR REPLACE, ON CONFLICT DO UPDATE), channel modes (changes(), total_changes main, total_changes main+other), and optional AFTER INSERT trigger; filter by receipts; answer only if all surviving candidates agree. Avoid 'del' syntax; use dict rebuild."}
